'use strict';

const path = require('path');
const { readFileSafe } = require('../utils/fs-safe');
const { stripJsonc } = require('../utils/jsonc');
const logger = require('../utils/logger');

const SCANNER_ID = 'lockfiles';
const MAX_LOCKFILE_BYTES = 64 * 1024 * 1024;

/**
 * Lockfiles beyond npm's package-lock.json. Each parser is a small, format-specific
 * reader (no YAML/TOML library), built and tested against lockfiles generated by the
 * real tools: pnpm 7/8/9+ (lockfile 5.4/6.0/9.0), yarn classic and Berry, bun.lock,
 * poetry, uv and pipenv. bun.lockb (binary) is reported as present but not parsed.
 */
const FORMATS = {
  'pnpm-lock.yaml': { kind: 'pnpm', ecosystem: 'npm', parse: parsePnpmLock },
  'yarn.lock': { kind: 'yarn', ecosystem: 'npm', parse: parseYarnLock },
  'bun.lock': { kind: 'bun', ecosystem: 'npm', parse: parseBunLock },
  'poetry.lock': { kind: 'poetry', ecosystem: 'pypi', parse: parsePoetryLock },
  'uv.lock': { kind: 'uv', ecosystem: 'pypi', parse: parseUvLock },
  'Pipfile.lock': { kind: 'pipenv', ecosystem: 'pypi', parse: parsePipfileLock },
};
const UNPARSED = { 'bun.lockb': 'binary bun lockfile (Bun < 1.2); run `bun install --save-text-lockfile` to produce bun.lock' };
const LOCKFILE_NAMES = [...Object.keys(FORMATS), ...Object.keys(UNPARSED)];

/**
 * foundFiles: Map<lockfile name, path[]> from the shared directory walk.
 * Returns { projects: [{ project, project_path, lockfile, lockfile_type, ecosystem,
 * total_dependencies, dependencies: [{ name, version }] }], unparsed: [{ lockfile, reason }] }.
 */
function scan(foundFiles) {
  const projects = [];
  const unparsed = [];
  for (const [name, fmt] of Object.entries(FORMATS)) {
    for (const file of (foundFiles.get(name) || [])) {
      const text = readFileSafe(file, { maxBytes: MAX_LOCKFILE_BYTES, skipLarger: true });
      if (text == null) continue;
      let dependencies;
      try {
        dependencies = dedupe(fmt.parse(text));
      } catch (e) {
        logger.debug(SCANNER_ID, `Could not parse ${file}: ${e.message}`);
        unparsed.push({ lockfile: file, reason: `parse error: ${e.message}` });
        continue;
      }
      const dir = path.dirname(file);
      projects.push({
        project: path.basename(dir),
        project_path: dir,
        lockfile: file,
        lockfile_type: fmt.kind,
        ecosystem: fmt.ecosystem,
        total_dependencies: dependencies.length,
        dependencies,
      });
    }
  }
  for (const [name, reason] of Object.entries(UNPARSED)) {
    for (const file of (foundFiles.get(name) || [])) unparsed.push({ lockfile: file, reason });
  }
  logger.info(SCANNER_ID, `Parsed ${projects.length} additional lockfiles (${projects.reduce((s, p) => s + p.total_dependencies, 0)} dependencies)`);
  return { projects, unparsed };
}

function dedupe(deps) {
  const seen = new Set();
  return deps.filter(d => {
    if (!d.name || !d.version || !/^\d/.test(d.version)) return false;
    const key = `${d.name}@${d.version}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

const unquote = (s) => s.trim().replace(/^(['"])(.*)\1$/, '$2');

// "name@version" with optional scope, e.g. "@types/node@20.11.0".
function splitAt(spec) {
  const at = spec.lastIndexOf('@');
  return at > 0 ? { name: spec.slice(0, at), version: spec.slice(at + 1) } : null;
}

/**
 * pnpm-lock.yaml, top-level "packages:" section, keys at two-space indent:
 *   9.0: 'lodash@4.17.21' / '@scope/x@1.0.0'
 *   6.0: /lodash@4.17.21, /react-dom@18.2.0(react@18.2.0)
 *   5.x: /lodash/4.17.21, /react-dom/18.2.0_react@18.2.0
 */
function parsePnpmLock(text) {
  const deps = [];
  const versionLine = text.match(/^lockfileVersion:\s*['"]?([\d.]+)/m);
  const legacy = versionLine && parseFloat(versionLine[1]) < 6;
  let inPackages = false;
  for (const line of text.split(/\r?\n/)) {
    if (/^\S/.test(line)) { inPackages = /^packages:\s*$/.test(line); continue; }
    if (!inPackages) continue;
    const m = line.match(/^ {2}(\S.*):\s*$/);
    if (!m) continue;
    let key = unquote(m[1]).replace(/^\//, '').replace(/\(.*$/, '');
    if (legacy) {
      key = key.replace(/_.*$/, '');
      const slash = key.lastIndexOf('/');
      if (slash > 0) deps.push({ name: key.slice(0, slash), version: key.slice(slash + 1) });
    } else {
      const parsed = splitAt(key);
      if (parsed) deps.push(parsed);
    }
  }
  return deps;
}

/**
 * yarn.lock. Classic (v1): header '"pkg@^1.0.0", pkg@~1.2.0:' then '  version "1.2.3"'.
 * Berry (v2+): header '"pkg@npm:^1.0.0":' then '  resolution: "pkg@npm:1.2.3"'.
 * Only npm-registry entries are kept (not workspace:, patch:, link:, git, file:).
 */
// Ranges that point outside the registry (git, tarball URLs, local paths, workspaces).
const NON_REGISTRY = /^(git|git\+\w+|github|file|link|portal|workspace|patch|https?):|^(\.{0,2}\/|~\/)|\.git(#|$)/;

function parseYarnLock(text) {
  const deps = [];
  const berry = /^__metadata:/m.test(text);
  for (const block of text.split(/\r?\n(?=\S)/)) {
    const lines = block.split(/\r?\n/);
    const header = lines[0];
    if (!header || header.startsWith('#') || header.startsWith('__metadata')) continue;
    if (berry) {
      const res = block.match(/^\s+resolution:\s*"?(.+?)"?\s*$/m);
      const m = res && res[1].match(/^(.+?)@npm:(\d[^\s"]*)$/);
      if (m) deps.push({ name: m[1], version: m[2] });
      continue;
    }
    const ver = block.match(/^\s+version\s+"?([^"\s]+)"?\s*$/m);
    if (!ver) continue;
    const firstSpec = unquote(header.replace(/:\s*$/, '').split(',')[0]);
    let spec = firstSpec;
    const alias = spec.match(/^.+?@npm:(.+)$/);
    if (alias) spec = alias[1];
    const parsed = splitAt(spec);
    if (parsed && !NON_REGISTRY.test(parsed.version)) deps.push({ name: parsed.name, version: ver[1] });
  }
  return deps;
}

// bun.lock (Bun 1.2+): JSONC; packages: { "<key>": ["name@version", registry, {...}, integrity] }.
function parseBunLock(text) {
  const data = JSON.parse(stripJsonc(text));
  const deps = [];
  for (const entry of Object.values((data && data.packages) || {})) {
    if (!Array.isArray(entry) || typeof entry[0] !== 'string') continue;
    const parsed = splitAt(entry[0]);
    if (parsed && !/^(workspace|link|file|github|git)[:+]/.test(parsed.version)) deps.push(parsed);
  }
  return deps;
}

// TOML [[package]] tables with name/version (and, for uv, a source table).
function tomlPackages(text) {
  const out = [];
  let current = null;
  for (const line of text.split(/\r?\n/)) {
    const t = line.trim();
    if (t.startsWith('[')) {
      current = t === '[[package]]' ? {} : null;
      if (current) out.push(current);
      continue;
    }
    if (!current) continue;
    const m = t.match(/^(name|version|source)\s*=\s*(.+)$/);
    if (m && !(m[1] in current)) current[m[1]] = m[1] === 'source' ? m[2] : unquote(m[2]);
  }
  return out;
}

function parsePoetryLock(text) {
  return tomlPackages(text).map(p => ({ name: p.name, version: p.version }));
}

// uv.lock: skip the project itself and local sources (virtual, editable, directory, path).
function parseUvLock(text) {
  return tomlPackages(text)
    .filter(p => !p.source || !/\b(virtual|editable|directory|path)\s*=/.test(p.source))
    .map(p => ({ name: p.name, version: p.version }));
}

function parsePipfileLock(text) {
  const data = JSON.parse(text);
  const deps = [];
  for (const section of ['default', 'develop']) {
    for (const [name, info] of Object.entries((data && data[section]) || {})) {
      const m = info && typeof info.version === 'string' && info.version.match(/^==\s*(.+)$/);
      if (m) deps.push({ name, version: m[1] });
    }
  }
  return deps;
}

module.exports = {
  scan, SCANNER_ID, LOCKFILE_NAMES,
  parsePnpmLock, parseYarnLock, parseBunLock, parsePoetryLock, parseUvLock, parsePipfileLock,
};
